namespace HelalHaram.Shared;
public static class PrivacyNotice
{
    public const string Limits = "Eksik içerik, okunamayan metin veya risk bulunamaması; helal onayı, alerjen yokluğu ya da tüketim güvenliği anlamına gelmez. Etiketteki alerjen ve eser miktar uyarılarını ayrıca kontrol edin. Kişisel alerjen filtresi henüz uygulanmadı. Makine çevirisi, özgün etiketin veya uzman değerlendirmesinin yerine geçmez.";
    public static IReadOnlyList<(string Title, string Text)> Sections { get; } = new (string, string)[]
    {
        ("Bu sürüm", "Bu açıklama geliştirme/test sürümü içindir. Veriler eksik veya eski olabilir. Yayından önce işletmeci, iletişim, saklama süreleri ve başvuru kanalı ayrıca belirlenmelidir."),
        ("Fotoğraf ve kamera", "Android uygulamasında barkod ve seçilen Latin, Çince, Japonca, Korece veya Devanagari OCR modeli cihazda işlenir. Fotoğraf analiz sunucusuna yüklenmez. İçerik analizini istediğinizde kontrol ettiğiniz metin ve dil uygulama sunucusuna gönderilir. Menü soruları cihazda hazırlanır. OCR için oluşturulan geçici işleme dosyası işlem sonunda silinir; kamera veya fotoğraf sağlayıcısının sakladığı asıl fotoğraf otomatik silinmez. İzinleri cihaz ayarlarından yönetebilirsiniz."),
        ("Etiket / menü çevirisi", "Çeviri düğmesini kullandığınızda onayladığınız metin sunucudan sunucunun bilgisayarındaki yerel LibreTranslate servisine gönderilir; fotoğraf gönderilmez. Etiket ön kontrolü için gerektiğinde ek İngilizce çeviri istenir. Özgün ve çevrilmiş metin uygulama veritabanına veya kalıcı çeviri önbelleğine yazılmaz; ekranda tutulur. Kişisel / sağlık bilgisi girmeyin. Yerel servis bilgisayarda çalışır; çeviri için Google veya Azure hesabı kullanılmaz. Sunucu teknik günlükleri istek yolu ve durumunu içerebilir; çeviri metni URL'ye eklenmez."),
        ("Soru kartları ve ses", "Sabit soru kartları uygulama kodunda bulunur; metinler çeviri API’sine gönderilmez. Web seslendirmesi yalnız tarayıcının yerel olarak bildirdiği sesleri kullanır. Mobil seslendirme cihazın metin okuma motorunu kullanır; motor ayarına göre internet erişimi ve kendi veri işleme koşulları olabilir. Mikrofon veya ses kaydı kullanılmaz. Soru sormak ve yanıt almak uygunluk ya da sertifika doğrulaması değildir."),
        ("Ürün sorguları", "Barkod sorgusu uygulama sunucusundan Open Food Facts'e gönderilir. Sonuçlar sunucuda geçici önbelleğe alınabilir. Kaynak veya belge bağlantısını açarsanız ilgili sitenin gizlilik koşulları geçerlidir. Harita ve seyahat ekranının veri işlemesi aşağıda açıklanır."),
        ("Harita ve seyahat", "Şehir adları paketlenmiş GeoNames verisinde aranır. Konum izni yalnız düğmeye basıldığında istenir; sürekli veya arka plan konum takibi yapılmaz. Arama onayınızla yaklaşık 0,01 dereceye yuvarlanmış bölge ekranda adı gösterilen Overpass servisine iletilir (geliştirme sürümünde VK Maps / maps.mail.ru); OSM kayıtları sunucuda 30 dakika RAM önbelleğinde tutulur. Hassas konum veritabanına yazılmaz. Harita görselleri için OpenStreetMap IP ve görüntülenen alanı görebilir. Konum POST gövdesinde gönderilir, arama URL’sine konmaz; form tarayıcı belleğinde kalabilir. Harita bağlantısını/yol tarifini açtığınızda ilgili sağlayıcının koşulları geçerlidir; yol tarifine yalnız işletmenin hedef koordinatı eklenir. OSM beyanları doğrulanmış helal sertifikası değildir."),
        ("Arayüz dili", "Arayüz dili webde en fazla 365 günlük helal-ui-language çerezinde, mobilde cihaz tercihlerinde saklanır. Bu tercih etiket/menü çevirisi yapmaz. Çerez veya uygulama verisini temizlemek dil tercihini de temizler."),
        ("Yerel veriler ve çerezler", "Mobil favoriler, kaçınılan içerik tercihi ve deneyim taslağı cihazda saklanır; hesaplar arasında eşitlenmez. Favorileri ve deneyim taslağını kendi ekranından silebilirsiniz. Kaçınılan içerik alanını boşaltıp kaydetmek tercihi temizler. Web favorileri en fazla 365 günlük korumalı çerezde saklanır; Favoriler ekranından temizlenebilir. Güvenlik ve oturum çerezleri de kullanılır. Yönetici oturumu en fazla 30 dakikadır; Çıkış yap ile kapatılabilir."),
        ("Uygulama geri bildirimi", "Geri bildirim formundaki açıklama, tür, platform, uygulama sürümü ve gönderim zamanı sunucuda saklanır; yalnız yetkili yöneticiye görünür. Ad, iletişim, sağlık bilgisi veya parola yazmayın. Otomatik yanıt ve otomatik silme süresi henüz yoktur."),
        ("Düzeltme önerileri", "Öneri, kaynak bağlantısı, ilgili kayıt ve zaman bilgisi sunucu veritabanında saklanır. Yetkili yönetici öneriyi ve karar geçmişini inceleyebilir; bunlar herkese açık listelenmez. Ad, telefon, sağlık bilgisi veya başkalarının özel bilgilerini yazmayın. Otomatik silme süresi ve kullanıcı silme başvuru ekranı henüz uygulanmadı."),
        ("Bağlantı ve teknik kayıtlar", "Sunucu IP adresi gibi teknik bağlantı bilgilerini işler; istek sınırlandırması IP'ye göre yapılır. Sunucu ve barındırma günlükleri teknik istek bilgileri içerebilir. Web içerik formu metni sayfa adresine ekler; metin tarayıcı geçmişinde ve adres kaydeden günlüklerde kalabilir. Kişisel veya hassas bilgi girmeyin; sonucu paylaşmadan önce adresi kontrol edin."),
        ("Sonuçların sınırları", Limits)
